export const MESSAGES = {
  en: { ...CORE_MESSAGES.en, ...EXTRA_MESSAGES.en },
  tr: { ...CORE_MESSAGES.tr, ...EXTRA_MESSAGES.tr },
} as const;

type Key = keyof typeof MESSAGES.en;
const LocaleContext = createContext<{ locale: Locale; setLocale: (locale: Locale) => void } | null>(null);
const localeListeners = new Set<() => void>();
function subscribeLocale(listener: () => void) { localeListeners.add(listener); window.addEventListener("storage", listener); return () => { localeListeners.delete(listener); window.removeEventListener("storage", listener); }; }
function getLocaleSnapshot(): Locale { try { return localStorage.getItem("repora.locale") === "tr" ? "tr" : "en"; } catch { return "en"; } }
function getServerLocaleSnapshot(): Locale { return "en"; }
export function LocaleProvider({ children }: { children: ReactNode }) {
  const locale = useSyncExternalStore(subscribeLocale, getLocaleSnapshot, getServerLocaleSnapshot);
  useEffect(() => { document.documentElement.lang = locale; }, [locale]);
  const setLocale = (next: Locale) => { try { localStorage.setItem("repora.locale", next); } catch { /* storage may be disabled */ } localeListeners.forEach((listener) => listener()); };
  const value = useMemo(() => ({ locale, setLocale }), [locale]);
  return <LocaleContext.Provider value={value}>{children}</LocaleContext.Provider>;
}
export function useLocale() {
  const context = useContext(LocaleContext);
  if (!context) throw new Error("useLocale must be used inside LocaleProvider");
  const t = (key: Key) => MESSAGES[context.locale][key];
  return { ...context, t, number: (value: number) => new Intl.NumberFormat(context.locale === "tr" ? "tr-TR" : "en-US").format(value), date: (value: string) => new Intl.DateTimeFormat(context.locale === "tr" ? "tr-TR" : "en-US", { dateStyle: "medium" }).format(new Date(value)) };
}
